// City Oversight — what the City Corporation is shown about its contractors:
// the overview, daily waste pickup, service growth, how complaints are
// answered, read-only registers and the agencies' targets. No money anywhere.
//
// Every figure comes from /api/reports/… (see server/swms/reports/oversight.py
// and city.py), scoped by the server to the signed-in user. One city at a time:
// the picker in the header sends `?city=` to every tab, so all tabs agree. A City
// Viewer bound to a city gets no picker — the server answers for their city.
// Exports are generated by the same endpoints (?format=…).

import { useCallback, useEffect, useMemo, useState } from 'react'
import { useSearchParams } from 'react-router-dom'
import { PageHeader, Section, StatCard, EmptyState } from '../components/ui.jsx'
import { IconChart, IconAlert, IconUsers, IconTruck, IconHome, IconCheck } from '../components/Icons.jsx'
import { useData } from '../context/DataContext.jsx'
import { useLang } from '../i18n/index.jsx'
import CollectionTab from './OversightCollection.jsx'
import { KpiScorecard } from './Reports.jsx'
import { ExportButtons, Failed, Loading } from './oversightParts.jsx'
import { DateRange } from './reportsShared.jsx'

const TABS = ['summary', 'collection', 'trend', 'complaints', 'registers', 'targets']
const GROUPS = ['agency', 'supervisor', 'collector', 'ward']
const REGISTERS = ['agencies', 'collectors', 'supervisors', 'vans', 'documents']

const isoDay = (d) => d.toISOString().slice(0, 10)
const daysAgo = (n) => { const d = new Date(); d.setDate(d.getDate() - n); return isoDay(d) }
const thisMonth = () => new Date().toISOString().slice(0, 7)

// One GET, three states; a failure says so rather than showing zeros.
export function useLoad(load, deps) {
  const [state, setState] = useState({ loading: true, data: null, error: null })
  const run = useCallback(() => {
    let live = true
    setState((s) => ({ ...s, loading: true, error: null }))
    load().then((data) => live && setState({ loading: false, data, error: null }))
      .catch((error) => live && setState({ loading: false, data: null, error }))
    return () => { live = false }
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, deps)
  useEffect(() => run(), [run])
  return { ...state, retry: run }
}

export function TrendBadge({ trend, pct }) {
  const { t, percent } = useLang()
  const tone = trend === 'up' ? 'ok' : trend === 'down' ? 'danger' : 'muted'
  const arrow = trend === 'up' ? '▲' : trend === 'down' ? '▼' : '■'
  return (
    <span className={`badge badge-${tone}`}>
      {arrow} {t(`oversight.trend.${trend || 'flat'}`)}{pct != null ? ` ${percent(Math.abs(pct))}` : ''}
    </span>
  )
}

// A table driven by [{key, label, get?}] — the same shape everywhere here.
export function Table({ columns, rows, rowKey }) {
  const { t } = useLang()
  if (!rows?.length) return <EmptyState>{t('oversight.empty')}</EmptyState>
  return (
    <div className="table-wrap">
      <table className="data">
        <thead><tr>{columns.map((c) => <th key={c.key}>{c.label}</th>)}</tr></thead>
        <tbody>
          {rows.map((r, i) => (
            <tr key={rowKey ? rowKey(r, i) : i}>
              {columns.map((c) => <td key={c.key} className={c.mono ? 'mono small' : undefined}>{c.get ? c.get(r) : (r[c.key] ?? '—')}</td>)}
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  )
}

// `city` is the user's pick ('' = the server's default, their first city).
const withCity = (city, params = {}) => (city ? { ...params, city } : params)

export default function Oversight() {
  const { t, lang } = useLang()
  const { api } = useData()
  const [search, setSearch] = useSearchParams()
  const tab = TABS.includes(search.get('tab')) ? search.get('tab') : 'summary'
  const city = search.get('city') || ''
  const update = (changes) => {
    const next = new URLSearchParams(search)
    for (const [key, value] of Object.entries(changes)) {
      if (value) next.set(key, value)
      else next.delete(key)
    }
    setSearch(next, { replace: true })
  }
  // The summary names the city answered for and the cities to pick from.
  const summary = useLoad(() => api.reports.oversight(withCity(city)), [api, city])
  const picked = summary.data?.city
  const cities = summary.data?.cities || []
  const cityName = picked ? (lang === 'bn' && picked.nameBn) || picked.name : ''

  return (
    <div className="fade-in">
      <PageHeader
        title={cityName ? t('oversight.titleCity', { city: cityName }) : t('oversight.title')}
        subtitle={t('oversight.subtitle')}
        actions={cities.length > 1 && (
          <select className="select" style={{ width: 'auto' }} value={city || picked?.id || ''}
            onChange={(e) => update({ city: e.target.value })} aria-label={t('oversight.pickCity')}>
            {cities.map((c) => <option key={c.id} value={c.id}>{(lang === 'bn' && c.nameBn) || c.name}</option>)}
          </select>
        )}
      />
      <div className="filter-bar">
        <div className="seg">
          {TABS.map((id) => (
            <button key={id} className={tab === id ? 'on' : ''}
              onClick={() => update({ tab: id === 'summary' ? '' : id })}>{t(`oversight.tab.${id}`)}</button>
          ))}
        </div>
      </div>
      {tab === 'summary' && (
        <>
          <Summary report={summary} />
          {/* The KPI scorecard (formerly on the Reports page), for the picked city. */}
          <div className="mt-24"><KpiScorecard extra={withCity(city)} /></div>
        </>
      )}
      {tab === 'collection' && <CollectionTab city={city} />}
      {tab === 'trend' && <ServiceTrend city={city} />}
      {tab === 'complaints' && <Complaints city={city} />}
      {tab === 'registers' && <Registers city={city} />}
      {tab === 'targets' && <Targets city={city} />}
    </div>
  )
}

/* ---------------- 6. Summary (the City Corporation dashboard) ---------------- */

export function Summary({ report }) {
  const { t, n, percent } = useLang()
  if (report.loading) return <Loading />
  if (report.error || !report.data) return <Failed error={report.error} onRetry={report.retry} />
  const d = report.data
  const pick = d.pickupToday
  const columns = [
    { key: 'rank', label: '#', get: (_, i) => n(i + 1) },
    { key: 'name', label: t('oversight.col.agency') },
    { key: 'registered', label: t('oversight.col.registered'), get: (r) => n(r.registered) },
    { key: 'served', label: t('oversight.col.served'), get: (r) => n(r.served) },
    { key: 'servedPct', label: t('oversight.col.servedPct'), get: (r) => percent(r.servedPct) },
    { key: 'trend', label: t('oversight.col.trend'), get: (r) => <TrendBadge trend={r.trend} /> },
    { key: 'collectedPct', label: t('oversight.col.collected30'), get: (r) => (r.collectedPct == null ? '—' : percent(r.collectedPct)) },
    { key: 'missed', label: t('oversight.col.missed30'), get: (r) => (r.missed ? <span className="badge badge-danger">{n(r.missed)}</span> : n(0)) },
    { key: 'complaints', label: t('oversight.col.complaints'), get: (r) => n(r.complaints) },
    { key: 'slaPct', label: t('oversight.col.slaPct'), get: (r) => (r.slaPct == null ? '—' : percent(r.slaPct)) },
    { key: 'per100', label: t('oversight.col.per100'), get: (r) => (r.per100 == null ? '—' : n(r.per100)) },
  ]
  return (
    <>
      <div className="stat-grid" style={{ marginBottom: 20 }}>
        <StatCard icon={<IconHome size={18} />} label={t('oversight.card.served')} value={n(d.served)}
          sub={<>{t('oversight.card.servedSub', { registered: n(d.registered), pct: percent(d.servedPct) })} <TrendBadge trend={d.trend} pct={d.changePct} /></>}
          progress={d.servedPct} />
        <StatCard icon={<IconChart size={18} />} tone="info" label={t('oversight.card.target')}
          value={d.target ? percent(d.targetPct) : '—'}
          sub={d.target ? t('oversight.card.targetSub', { served: n(d.targetServed), target: n(d.target) }) : t('oversight.card.noTarget')}
          progress={d.target ? d.targetPct : 0} />
        {pick && (
          <StatCard icon={<IconCheck size={18} />} tone="ok" label={t('oversight.card.pickup')}
            value={n(pick.confirmed + pick.auto)}
            sub={t('oversight.card.pickupSub', { due: n(pick.due), pending: n(pick.pending) })}
            progress={pick.due ? ((pick.confirmed + pick.auto) / pick.due) * 100 : 0} />
        )}
        <StatCard icon={<IconAlert size={18} />} tone={d.complaintsOverdue ? 'danger' : 'warn'} label={t('oversight.card.complaints')}
          value={n(d.complaintsOpen)} sub={t('oversight.card.complaintsSub', { overdue: n(d.complaintsOverdue), sla: percent(d.slaPct) })} />
        <StatCard icon={<IconUsers size={18} />} tone="ok" label={t('oversight.card.collectors')}
          value={n(d.collectorsCheckedIn)} sub={t('oversight.card.collectorsSub', { total: n(d.collectorsActive) })}
          progress={d.collectorsActive ? (d.collectorsCheckedIn / d.collectorsActive) * 100 : 0} />
        <StatCard icon={<IconTruck size={18} />} tone="info" label={t('oversight.card.vans')}
          value={n(d.vansActive)} sub={t('oversight.card.vansSub', { total: n(d.vansTotal) })}
          progress={d.vansTotal ? (d.vansActive / d.vansTotal) * 100 : 0} />
      </div>
      <Section title={t('oversight.league', { period: d.period })} pad={false}>
        <div className="table-wrap">
          <table className="data">
            <thead><tr>{columns.map((c) => <th key={c.key}>{c.label}</th>)}</tr></thead>
            <tbody>
              {d.league.map((r, i) => (
                <tr key={r.agency || i}>{columns.map((c) => <td key={c.key}>{c.get ? c.get(r, i) : r[c.key]}</td>)}</tr>
              ))}
            </tbody>
          </table>
          {!d.league.length && <EmptyState>{t('oversight.empty')}</EmptyState>}
        </div>
        <div className="tiny muted-3" style={{ padding: '12px 20px' }}>{t('oversight.leagueNote')}</div>
      </Section>
    </>
  )
}

/* ---------------- 2. Service trend ---------------- */

function ServiceTrend({ city }) {
  const { t, n, percent } = useLang()
  const { api } = useData()
  const [by, setBy] = useState('agency')
  const [mode, setMode] = useState('monthly')
  const [all, setAll] = useState(false)
  const params = withCity(city, { by, mode })
  const report = useLoad(() => api.reports.serviceTrend.load(params), [api, by, mode, city])

  const rows = useMemo(() => {
    const list = report.data?.rows || []
    if (all) return list
    // Latest period per group: what it is now, and which way it is moving.
    const latest = new Map()
    for (const r of list) {
      const seen = latest.get(r.group)
      if (!seen || r.period > seen.period) latest.set(r.group, r)
    }
    return [...latest.values()].sort((a, b) => b.served - a.served)
  }, [report.data, all])

  const columns = [
    { key: 'name', label: t(`oversight.by.${by}`) },
    { key: 'period', label: t('oversight.col.period'), mono: true },
    { key: 'registered', label: t('oversight.col.registered'), get: (r) => n(r.registered) },
    { key: 'served', label: t('oversight.col.served'), get: (r) => n(r.served) },
    { key: 'servedPct', label: t('oversight.col.servedPct'), get: (r) => percent(r.servedPct) },
    { key: 'new', label: t('oversight.col.new'), get: (r) => n(r.new) },
    { key: 'dropped', label: t('oversight.col.dropped'), get: (r) => n(r.dropped) },
    { key: 'change', label: t('oversight.col.change'), get: (r) => (r.change == null ? '—' : `${r.change > 0 ? '+' : ''}${n(r.change)}`) },
    { key: 'trend', label: t('oversight.col.trend'), get: (r) => <TrendBadge trend={r.trend} pct={r.changePct} /> },
  ]
  return (
    <>
      <div className="filter-bar">
        <div className="seg">
          {GROUPS.map((g) => <button key={g} className={by === g ? 'on' : ''} onClick={() => setBy(g)}>{t(`oversight.by.${g}`)}</button>)}
        </div>
        <div className="seg">
          {['monthly', 'yearly'].map((m) => <button key={m} className={mode === m ? 'on' : ''} onClick={() => setMode(m)}>{t(`oversight.mode.${m}`)}</button>)}
        </div>
        <label className="check"><input type="checkbox" checked={all} onChange={(e) => setAll(e.target.checked)} /><span>{t('oversight.allPeriods')}</span></label>
        <div className="grow" />
        <ExportButtons filename={`service_trend_${by}_${mode}`} exporter={(p) => api.reports.serviceTrend.export({ ...params, ...p })} />
      </div>
      <Section title={t('oversight.trendTitle')} pad={false}>
        {report.loading ? <Loading /> : report.error ? <Failed error={report.error} onRetry={report.retry} />
          : <Table columns={columns} rows={rows} rowKey={(r) => `${r.group}-${r.period}`} />}
        <div className="tiny muted-3" style={{ padding: '12px 20px' }}>{t('oversight.trendNote')}</div>
      </Section>
    </>
  )
}

/* ---------------- 3. Complaints ---------------- */

// `source` is the report group (api.reports, or api.reports.agency for Agency
// Reports); `extra` is sent with every request (the city, or the agency).
export function Complaints({ city, source, extra, groups = GROUPS }) {
  const { t, n, percent, date } = useLang()
  const { api } = useData()
  const reports = source || api.reports
  const more = extra || withCity(city)
  const [by, setBy] = useState(groups[0])
  const [from, setFrom] = useState(daysAgo(29))
  const [to, setTo] = useState(isoDay(new Date()))
  const params = { ...more, by, from, to }
  const key = JSON.stringify(more)
  const perf = useLoad(() => reports.complaintPerformance.load(params), [reports, by, from, to, key])
  const overdue = useLoad(() => reports.complaintsOverdue.load(more), [reports, key])
  const typeLabel = (k) => t(`complaints.type.${k}`)

  const perfColumns = [
    { key: 'name', label: t(`oversight.by.${by}`), get: (r) => (by === 'type' ? typeLabel(r.group) : r.name) },
    { key: 'received', label: t('oversight.col.received'), get: (r) => n(r.received) },
    { key: 'resolved', label: t('oversight.col.resolved'), get: (r) => n(r.resolved) },
    { key: 'slaPct', label: t('oversight.col.slaPct'), get: (r) => percent(r.slaPct) },
    { key: 'avgResolveH', label: t('oversight.col.avgHours'), get: (r) => (r.avgResolveH == null ? '—' : n(r.avgResolveH)) },
    { key: 'reopened', label: t('oversight.col.reopened'), get: (r) => n(r.reopened) },
    { key: 'openNow', label: t('oversight.col.openNow'), get: (r) => n(r.openNow) },
    { key: 'overdueNow', label: t('oversight.col.overdueNow'), get: (r) => (r.overdueNow ? <span className="badge badge-danger">{n(r.overdueNow)}</span> : n(0)) },
    { key: 'per100', label: t('oversight.col.per100'), get: (r) => (r.per100 == null ? '—' : n(r.per100)) },
  ]
  const natureColumns = [
    { key: 'type', label: t('oversight.col.type'), get: (r) => typeLabel(r.type) },
    { key: 'count', label: t('oversight.col.thisPeriod'), get: (r) => n(r.count) },
    { key: 'previous', label: t('oversight.col.previous'), get: (r) => n(r.previous) },
    { key: 'trend', label: t('oversight.col.change'), get: (r) => <TrendBadge trend={r.trend} pct={r.changePct} /> },
    { key: 'share', label: t('oversight.col.share'), get: (r) => percent(r.share) },
  ]
  const overdueColumns = [
    { key: 'id', label: t('oversight.col.complaint'), mono: true },
    { key: 'type', label: t('oversight.col.type'), get: (r) => typeLabel(r.type) },
    { key: 'priority', label: t('oversight.col.priority'), get: (r) => t(`complaints.priority.${r.priority}`) },
    { key: 'wardName', label: t('oversight.col.ward') },
    { key: 'agency', label: t('oversight.col.agency'), get: (r) => r.agency || '—' },
    { key: 'assigned', label: t('oversight.col.assigned'), get: (r) => r.assigned || t('oversight.unassigned') },
    { key: 'opened', label: t('oversight.col.opened'), get: (r) => date(r.opened) },
    { key: 'overdueH', label: t('oversight.col.overdueBy'), get: (r) => <span className="badge badge-danger">{t('oversight.hours', { h: n(r.overdueH) })}</span> },
  ]
  return (
    <>
      <div className="filter-bar">
        <div className="seg">
          {[...groups, 'type'].map((g) => <button key={g} className={by === g ? 'on' : ''} onClick={() => setBy(g)}>{t(`oversight.by.${g}`)}</button>)}
        </div>
        <DateRange from={from} to={to} setFrom={setFrom} setTo={setTo} />
        <div className="grow" />
        <ExportButtons filename={`complaint_performance_${by}`} exporter={(p) => reports.complaintPerformance.export({ ...params, ...p })} />
      </div>
      <Section title={t('oversight.natureTitle')} pad={false}>
        {perf.loading ? <Loading /> : perf.error ? <Failed error={perf.error} onRetry={perf.retry} />
          : <Table columns={natureColumns} rows={perf.data?.nature} rowKey={(r) => r.type} />}
      </Section>
      <Section title={t('oversight.performanceTitle')} pad={false}>
        {perf.loading ? <Loading /> : perf.error ? null
          : <Table columns={perfColumns} rows={perf.data?.rows} rowKey={(r, i) => `${r.group}-${i}`} />}
        <div className="tiny muted-3" style={{ padding: '12px 20px' }}>{t('oversight.slaNote')}</div>
      </Section>
      <Section title={t('oversight.overdueTitle')} pad={false}
        actions={<ExportButtons filename="complaints_overdue" exporter={(p) => reports.complaintsOverdue.export({ ...more, ...p })} />}>
        {overdue.loading ? <Loading /> : overdue.error ? <Failed error={overdue.error} onRetry={overdue.retry} />
          : <Table columns={overdueColumns} rows={overdue.data?.rows} rowKey={(r) => r.id} />}
      </Section>
    </>
  )
}

/* ---------------- 4. Registers ---------------- */

export function Registers({ city, source, extra, kinds = REGISTERS }) {
  const { t, n, percent, date } = useLang()
  const { api } = useData()
  const reports = source || api.reports
  const more = extra || withCity(city)
  const key = JSON.stringify(more)
  const [kind, setKind] = useState(kinds[0])
  const report = useLoad(() => reports.register(kind).load(more), [reports, kind, key])
  const d = (v) => (v ? date(v) : '—')
  const status = (v) => (v ? t(`status.${v}`) === `status.${v}` ? String(v).replace(/_/g, ' ') : t(`status.${v}`) : '—')
  const COLUMNS = {
    agencies: [
      { key: 'name', label: t('oversight.col.agency') }, { key: 'type', label: t('oversight.col.type') },
      { key: 'district', label: t('holdings.district') }, { key: 'cities', label: t('holdings.city') },
      { key: 'contractEnd', label: t('oversight.col.contractEnd'), get: (r) => d(r.contractEnd) },
      { key: 'status', label: t('oversight.col.status'), get: (r) => status(r.status) },
      { key: 'collectors', label: t('oversight.col.collectors'), get: (r) => n(r.collectors) },
      { key: 'vans', label: t('oversight.col.vans'), get: (r) => n(r.vans) },
      { key: 'holdings', label: t('oversight.col.registered'), get: (r) => n(r.holdings) },
      { key: 'target', label: t('oversight.col.target'), get: (r) => (r.target == null ? '—' : n(r.target)) },
    ],
    collectors: [
      { key: 'name', label: t('oversight.col.collector') }, { key: 'dspId', label: 'DSP ID', mono: true },
      { key: 'phone', label: t('oversight.col.phone'), mono: true }, { key: 'agency', label: t('oversight.col.agency') },
      { key: 'city', label: t('holdings.city') }, { key: 'wards', label: t('oversight.col.wards') },
      { key: 'van', label: t('oversight.col.van'), mono: true },
      { key: 'licenseExp', label: t('oversight.col.licenceExp'), get: (r) => d(r.licenseExp) },
      { key: 'attendance', label: t('oversight.col.attendance'), get: (r) => status(r.attendance) },
      { key: 'coverage', label: t('oversight.col.coverage'), get: (r) => percent(r.coverage || 0) },
    ],
    supervisors: [
      { key: 'name', label: t('oversight.col.supervisor') }, { key: 'phone', label: t('oversight.col.phone'), mono: true },
      { key: 'agency', label: t('oversight.col.agency'), get: (r) => r.agency || '—' },
      { key: 'area', label: t('oversight.col.area'), get: (r) => t(`users.scope.${r.area}`) },
      { key: 'wards', label: t('oversight.col.wards'), get: (r) => n(r.wards) },
      { key: 'collectors', label: t('oversight.col.collectors'), get: (r) => n(r.collectors) },
      { key: 'openComplaints', label: t('oversight.col.openNow'), get: (r) => n(r.openComplaints) },
    ],
    vans: [
      { key: 'id', label: t('oversight.col.van'), mono: true }, { key: 'plate', label: t('oversight.col.plate'), mono: true },
      { key: 'status', label: t('oversight.col.status'), get: (r) => status(r.status) },
      { key: 'agency', label: t('oversight.col.agency'), get: (r) => r.agency || '—' },
      { key: 'driver', label: t('oversight.col.driver'), get: (r) => r.driver || '—' },
      { key: 'driverPhone', label: t('oversight.col.phone'), mono: true },
      { key: 'driverLicense', label: t('oversight.col.licence'), mono: true },
      { key: 'driverLicenseExp', label: t('oversight.col.licenceExp'), get: (r) => d(r.driverLicenseExp) },
      { key: 'documentsDue', label: t('oversight.col.papersDue'), get: (r) => r.documentsDue || '—' },
    ],
    documents: [
      { key: 'kind', label: t('oversight.col.kind'), get: (r) => t(`oversight.kind.${r.kind}`) },
      { key: 'subject', label: t('oversight.col.subject') },
      { key: 'agency', label: t('oversight.col.agency'), get: (r) => r.agency || '—' },
      { key: 'document', label: t('oversight.col.document'), get: (r) => t(`oversight.doc.${r.document}`) },
      { key: 'expires', label: t('oversight.col.expires'), get: (r) => d(r.expires) },
      { key: 'days', label: t('oversight.col.daysLeft'), get: (r) => <span className={`badge ${r.days < 0 ? 'badge-danger' : 'badge-warn'}`}>{n(r.days)}</span> },
    ],
  }
  return (
    <>
      <div className="filter-bar">
        <div className="seg">
          {kinds.map((k) => <button key={k} className={kind === k ? 'on' : ''} onClick={() => setKind(k)}>{t(`oversight.register.${k}`)}</button>)}
        </div>
        <div className="grow" />
        <ExportButtons filename={`register_${kind}`} exporter={(p) => reports.register(kind).export({ ...more, ...p })} />
      </div>
      <Section title={t(`oversight.register.${kind}`)} pad={false}>
        {report.loading ? <Loading /> : report.error ? <Failed error={report.error} onRetry={report.retry} />
          : <Table columns={COLUMNS[kind]} rows={report.data?.rows} rowKey={(r, i) => `${r.id || r.subject}-${i}`} />}
      </Section>
    </>
  )
}

/* ---------------- 5. Targets ---------------- */

function Targets({ city }) {
  const { t, n, percent } = useLang()
  const { api } = useData()
  const [period, setPeriod] = useState(thisMonth())
  const report = useLoad(() => api.reports.agencyTargets.load(withCity(city, { period })), [api, period, city])
  const tone = { good: 'ok', fair: 'warn', poor: 'danger' }
  const columns = [
    { key: 'name', label: t('oversight.col.agency') },
    { key: 'target', label: t('oversight.col.target'), get: (r) => (r.target == null ? <span className="muted-3">{t('oversight.noTarget')}</span> : n(r.target)) },
    { key: 'registered', label: t('oversight.col.registered'), get: (r) => n(r.registered) },
    { key: 'served', label: t('oversight.col.served'), get: (r) => n(r.served) },
    { key: 'achievement', label: t('oversight.col.achievement'), get: (r) => (r.achievement == null ? '—'
      : <span className={`badge badge-${tone[r.status] || 'muted'}`}>{percent(r.achievement)}</span>) },
    { key: 'new', label: t('oversight.col.new'), get: (r) => n(r.new) },
    { key: 'dropped', label: t('oversight.col.dropped'), get: (r) => n(r.dropped) },
  ]
  return (
    <>
      <div className="filter-bar">
        <input className="input" type="month" value={period} onChange={(e) => setPeriod(e.target.value || thisMonth())} aria-label={t('oversight.col.period')} />
        <div className="grow" />
        <ExportButtons filename={`agency_targets_${period}`} exporter={(p) => api.reports.agencyTargets.export(withCity(city, { period, ...p }))} />
      </div>
      <Section title={t('oversight.targetsTitle')} pad={false}>
        {report.loading ? <Loading /> : report.error ? <Failed error={report.error} onRetry={report.retry} />
          : <Table columns={columns} rows={report.data?.rows} rowKey={(r) => r.agency} />}
        <div className="tiny muted-3" style={{ padding: '12px 20px' }}>{t('oversight.targetsNote')}</div>
      </Section>
    </>
  )
}
